import "../../styles/index-base.css";
import "../../styles/components/toast.css";
import { Toaster as SonnerToaster, toast as sonnerToast } from "sonner";

export function Toaster() {
  return (
    <SonnerToaster
      className="ix-toaster"
      position="bottom-right"
      closeButton
      gap={8}
      toastOptions={{
        unstyled: true,
        classNames: {
          toast: "ix-toast",
          content: "ix-toast__content",
          title: "ix-toast__title",
          description: "ix-toast__description",
          actionButton: "ix-toast__action",
          closeButton: "ix-toast__close",
        },
      }}
    />
  );
}

export const toast = sonnerToast;

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-toaster { z-index: var(--ix-layer-toast); }

.ix-toast { position: relative; display: flex; width: 326px; min-height: 52px; align-items: center; gap: 10px; padding: 10px 40px 10px 12px; border-radius: 8px; background: var(--ix-bg-flyout); color: var(--ix-ink); box-shadow: var(--ix-shadow-flyout); font-family: inherit; }

.ix-toast__content { display: grid; flex: 1; gap: 2px; }

.ix-toast__title { font-size: 13.5px; font-weight: 580; }

.ix-toast__description { color: var(--ix-ink-secondary); font-size: 12px; }

.ix-toast__action { height: 28px; padding: 0 8px; border: 1px solid var(--ix-border); border-radius: 5px; background: var(--ix-control-surface); color: var(--ix-ink); font-size: 12px; font-weight: 550; }

.ix-toast__close { position: absolute; top: 8px; right: 8px; display: grid; width: 22px; height: 22px; padding: 0; place-items: center; border: 0; border-radius: 4px; background: transparent; color: var(--ix-fg-subtle); }

@media (forced-colors: active) {
.ix-toast { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }
}
}
